# Generated by `roundhouse --target fractal`. Do not edit: rerun the
# transpile instead.
#
# Query chains in the selected classes that Roundhouse found to be static,
# hoisted out of the request. Each `define` holds a chain's Relation with a
# bind placeholder for every value only known at request time. The first request on a
# connection kind builds it once, in Rails, so the SQL, the preload trees
# and the strict-loading setting are all Rails' own. Rails compiles it into
# an ActiveRecord::StatementCache, the mechanism behind `find_by`; each
# request only executes it, then does what Relation#load would have done
# next: mark association records the way AssociationRelation does, preload
# (see Fractal::Preload), and reverse a `last(n)`.
#
# The call site keeps the original chain as a block, and it runs instead
# whenever the statement cannot be trusted to give Rails' answer:
#
# - a request-time value StatementCache refuses (nil, an Array, a Range, a
#   record...);
# - the model is inside a `scoping`/`unscoped` block, or an association
#   scope, which Rails' own `find_by` statement cache also steps around
#   (a statement built under one caller's scope must not answer another's);
# - the model constant was reloaded and the call site still names the old
#   class;
# - the app or a gem redefined the finder (`via:`) or the association
#   reader, so going around it would skip the app's own code;
# - the built Relation needs something a StatementCache cannot do (eager
#   loading), building it raises, or its binds do not line up one for one,
#   in order, with the values the call site passes.
#
# A statement is built per model class, database configuration and
# prepared-statements setting, so a reload or a second database gets its
# own. With FRACTAL_VERIFY=1 the original runs as well, to check that both
# give the same records in the same order, with the same associations
# loaded. `Fractal.counts` says how often each site took the fast path
# and, for every fallback, why.
module Fractal
  Statement = Struct.new(:model, :build, :reverse, :one, :via, keyword_init: true)
  Compiled = Struct.new(:cache, :preload, :strict_loading, :arity, keyword_init: true)

  # Records each placeholder in the order the block asks for it, so the
  # built statement can be checked against the call site's value order.
  class Params
    attr_reader :issued

    def initialize
      @params = ActiveRecord::StatementCache::Params.new
      @issued = []
    end

    def bind
      @params.bind.tap { |substitute| @issued << substitute }
    end
  end

  @statements = {}
  @compiled = Concurrent::Map.new
  @readers = Concurrent::Map.new
  @counts = Concurrent::Map.new
  VERIFY = ENV["FRACTAL_VERIFY"] == "1"

  class << self
    # `reverse:` for `last(n)`, whose rows Rails loads newest first and
    # reverses; `one:` for `first`/`last`/`take`/`find_by`, which return
    # the first loaded record or nil; `via:` names the Rails finder the
    # chain ends in, which must still be Rails' when the statement is built.
    # Run first in every `to_prepare`, at boot and after each code reload:
    # forget everything built for the classes the reload retired, so a
    # long-running development server does not keep every generation of
    # model classes and their reflections alive.
    def prepare
      @compiled.clear
      @readers.clear
      Preload.reset
    end

    def define(key, model, reverse: false, one: false, via: nil, &build)
      @statements[key] = Statement.new(model: model, build: build, reverse: reverse, one: one, via: via)
      # A redefinition (a code reload) retires what was built for the old class.
      @compiled.each_key { |k| @compiled.delete(k) if k.first == key }
    end

    def records(key, binds, owner: nil, association: nil, &fallback)
      statement = @statements.fetch(key)
      model = statement.model
      reason = refusal(model, binds, owner, association)
      return fall_back(key, reason, &fallback) if reason

      compiled = nil
      records = model.with_connection do |connection|
        compiled = @compiled.compute_if_absent([key, model, connection.pool.db_config, connection.prepared_statements]) do
          compile(statement, connection)
        end
        compiled && compiled.arity == binds.size && compiled.cache.execute(binds, connection)
      end
      return fall_back(key, compiled ? :arity : :uncompilable, &fallback) unless records

      if owner
        proxy = owner.association(association)
        records.each do |record|
          proxy.set_inverse_instance_from_queries(record)
          proxy.set_strict_loading(record)
        end
      end
      compiled.preload.each do |associations|
        Preload.call(records, associations, strict: compiled.strict_loading)
      end
      # As Relation#load does: an explicit `strict_loading(false)` turns it
      # off even where the model turns it on by default.
      records.each { |record| record.strict_loading!(compiled.strict_loading) } unless compiled.strict_loading.nil?
      records.reverse! if statement.reverse
      result = statement.one ? records.first : records
      count(key, :fast)

      verify(key, result, fallback.call, compiled.preload) if VERIFY
      result
    end

    # `{ key => { fast: n, <fallback reason>: n } }` since boot (or the last
    # `reset_counts`).
    def counts
      @counts.each_pair.with_object(Hash.new { |h, k| h[k] = Hash.new(0) }) do |((key, outcome), n), out|
        out[key][outcome] = n
      end
    end

    def fast_path_count(key)
      @counts.fetch([key, :fast], 0)
    end

    def reset_counts
      @counts.clear
    end

    private

    def count(key, outcome)
      @counts.compute([key, outcome]) { |n| (n || 0) + 1 }
    end

    def fall_back(key, reason, &fallback)
      count(key, reason)
      fallback.call
    end

    # Why this call must take the original chain, or nil.
    def refusal(model, binds, owner, association)
      return :unsupported_value if binds.any? { |value| ActiveRecord::StatementCache.unsupported_value?(value) }
      return :scoped if model.scope_attributes?
      return :reloaded unless current_class?(model)
      return :association_redefined if owner && !rails_reader?(owner.class, association)

      nil
    end

    # After a reload the constant names a new class; the define for it
    # arrives with `to_prepare`, and until then the old one must not answer.
    def current_class?(model)
      Object.const_get(model.name).equal?(model)
    rescue NameError, TypeError
      false
    end

    def rails_reader?(klass, association)
      @readers.compute_if_absent([klass, association]) do
        # The reader Rails generated lives in the module of the class that
        # declared the association, which for an STI subclass is a parent.
        declared_in = klass._reflect_on_association(association)&.active_record
        !declared_in.nil? && klass.instance_method(association).owner.equal?(declared_in.generated_association_methods)
      rescue NameError
        false
      end
    end

    # Build the Relation once and keep what loading it needs. `false` (not
    # nil, so compute_if_absent remembers it) when Rails would load it in a
    # way a StatementCache cannot reproduce, or the app's own code would be
    # skipped.
    def compile(statement, connection)
      model = statement.model
      return false if statement.via && redefined?(model, statement.via)

      params = Params.new
      # Building can raise where Rails will not take a placeholder: Active
      # Record 8.1 casts a LIMIT with Integer() as it is set, so
      # `limit(p.bind)` raises here. The original chain does not, so it
      # answers instead.
      relation = begin
        statement.build.call(params)
      rescue StandardError
        return false
      end
      return false unless relation.model.equal?(model)
      return false if relation.eager_loading? || relation.readonly_value || relation.extending_values.any?

      # ActiveRecord::StatementCache.create, with one check in the middle:
      # the placeholders Rails collected, in SQL order, are exactly the
      # ones the block issued, in the order the call site passes values.
      query_builder, bound = connection.cacheable_query(ActiveRecord::StatementCache, relation.arel)
      substitutes = bound.filter_map do |attribute|
        attribute.value if ActiveModel::Attribute === attribute && ActiveRecord::StatementCache::Substitute === attribute.value
      end
      return false unless substitutes.size == params.issued.size && substitutes.zip(params.issued).all? { |a, b| a.equal?(b) }

      cache = ActiveRecord::StatementCache.new(query_builder, ActiveRecord::StatementCache::BindMap.new(bound), model)
      preload = relation.preload_values + relation.includes_values
      Compiled.new(cache: cache, preload: preload, strict_loading: relation.strict_loading_value, arity: substitutes.size)
    end

    # Is the finder the chain ends in still Active Record's own, on the
    # model and on its relations?
    def redefined?(model, via)
      methods = [model.all.method(via)]
      methods << model.method(via) if model.respond_to?(via)
      methods.any? { |m| !m.owner.name.to_s.start_with?("ActiveRecord::") }
    rescue NameError
      true
    end

    def verify(key, result, expected, preload)
      got = Array(result).map(&:id)
      want = Array(expected).map(&:id)
      raise "fractal #{key}: specialized #{got.inspect} != Rails #{want.inspect}" unless got == want
      preload.each do |spec|
        mine = Preload.signature(Array(result), spec)
        rails = Preload.signature(Array(expected), spec)
        raise "fractal #{key}: preloaded #{spec.inspect} differs from Rails" unless mine == rails
      end
    end
  end

  # One preload entry (one element of a Relation's preload_values or
  # includes_values), loaded the way ActiveRecord::Associations::Preloader
  # loads it, minus the work that does not depend on the request.
  #
  # The Preloader rebuilds, for every call, the branch tree, each
  # association's scope (the target's scope_for_association, the
  # polymorphic type condition, the reflection's own scope) and the loader
  # queries that group similar associations. For a given tree and owner
  # class none of that changes, so it is planned once here, and each call
  # runs only what Preloader::Association does per call: key the owners,
  # skip owners already loaded, load the missing keys with
  # `scope.where(key => keys)` (one query per group of loaders on a level
  # whose query is the same, as Preloader::Batch groups them), set inverses,
  # and assign targets.
  #
  # An entry is planned only when every association in its tree is one
  # whose scope can be built once: not `through:`, not a polymorphic
  # belongs_to, no composite key, no owner-dependent scope, a target with no
  # default_scope, and a scope that is either absent, defined by Active
  # Storage or Action Text, or certified static by Roundhouse
  # (`static_scopes`, from the app's own association declarations). Any
  # other entry is handed to Rails' Preloader whole.
  module Preload
    Node = Struct.new(:name, :reflection, :children, :spec)
    FRAMEWORK = %r{/(activestorage|actiontext)/}

    @plans = Concurrent::Map.new
    @scopes = Concurrent::Map.new
    @static_scopes = Set.new

    class << self
      # "Owner#association" names whose scope lambda Roundhouse found to
      # build a relation from literals only.
      def static_scopes(*names)
        @static_scopes.merge(names)
      end

      # Plans and scopes are keyed by classes and reflections; `prepare`
      # drops them with the classes a reload retires.
      def reset
        @plans.clear
        @scopes.clear
      end

      def call(records, spec, strict:)
        return if records.empty?

        root = records.first.class
        roots = @plans.compute_if_absent([spec, root]) { plan(spec, root) || false }
        if !roots || records.any? { |r| !r.instance_of?(root) } || scoped?(roots)
          return rails(records, spec, strict)
        end

        level = roots.map { |node| [node, records] }
        until level.empty?
          loaders = []
          level.each do |node, owners|
            next if owners.empty?
            if owners.all? { |o| o.class._reflect_on_association(node.name).equal?(node.reflection) }
              loaders << Loader.new(node, owners, scope_for(node.reflection, owners.first.class, strict))
            else
              # An STI subclass redeclared the association: Rails' own path.
              rails(owners, node.spec, strict)
            end
          end
          loaders.group_by(&:query_key).each_value { |similar| load_batch(similar) }
          loaders.each(&:run)
          level = loaders.flat_map { |l| l.node.children.map { |child| [child, l.preloaded_records] } }
        end
      end

      # Which associations a preload loaded, and to what, through the tree.
      def signature(records, spec)
        nodes(spec).map do |name, child|
          records.map do |record|
            association = record.association(name)
            targets = Array.wrap(association.target)
            [record.id, association.loaded?, targets.map(&:id), child ? signature(targets, child) : nil]
          end
        end
      end

      private

      def rails(records, spec, strict)
        scope = strict ? ActiveRecord::Relation::StrictLoadingScope : nil
        ActiveRecord::Associations::Preloader.new(records: records, associations: spec, scope: scope).call
      end

      # The children of a preload spec, exactly as Preloader::Branch reads them.
      def nodes(spec)
        Array.wrap(spec).flat_map { |a| Array(a).flat_map { |parent, child| [[parent.to_sym, child]] } }
      end

      def plan(spec, klass)
        nodes(spec).map do |name, child|
          reflection = klass._reflect_on_association(name)
          return nil unless plannable?(reflection)

          children = child ? plan(child, reflection.klass) : []
          return nil unless children

          Node.new(name, reflection, children, child ? { name => child } : name)
        end
      end

      def plannable?(reflection)
        return false unless reflection
        return false if reflection.options[:through] || reflection.polymorphic?
        return false if reflection.scope && reflection.scope.arity != 0
        return false if reflection.join_primary_key.is_a?(Array) || reflection.join_foreign_key.is_a?(Array)

        klass = reflection.klass
        return false if klass.abstract_class? || klass.default_scopes.any?

        reflection.scope.nil? ||
          FRAMEWORK.match?(scope_source(reflection.scope)) ||
          @static_scopes.include?("#{reflection.active_record.name}##{reflection.name}")
      end

      # Where a scope lambda was written. Rails' association builder wraps an
      # argument-less scope as `proc { instance_exec(&scope) }`, so look
      # through the wrapper to the lambda it closes over.
      def scope_source(scope)
        location = scope.source_location&.first.to_s
        if location.end_with?("associations/builder/association.rb") && scope.binding.local_variable_defined?(:scope)
          location = scope.binding.local_variable_get(:scope).source_location&.first.to_s
        end
        location
      end

      # A `Model.scoping { }` block changes scope_for_association.
      def scoped?(nodes)
        nodes.any? { |n| n.reflection.klass.current_scope || scoped?(n.children) }
      end

      # Preloader::Association#build_scope, built once per association,
      # owner class and strictness.
      def scope_for(reflection, model, strict)
        @scopes.compute_if_absent([reflection, model, strict]) do
          klass = reflection.klass
          scope = klass.scope_for_association
          scope.where!(reflection.type => model.polymorphic_name) if reflection.type && !reflection.through_reflection?
          reflection_scope = reflection.join_scopes(klass.arel_table, klass.predicate_builder, klass).inject(klass.unscoped, &:merge!)
          scope.merge!(reflection_scope) unless reflection_scope.empty_scope?
          scope = scope.strict_loading if strict
          [scope, scope.values_for_queries]
        end
      end

      # Preloader::Association::LoaderRecords: keys of owners not yet
      # loaded, one query for the group, inverses set as records load.
      def load_batch(loaders)
        keys = Set.new
        already = {}
        loaders.each do |loader|
          loader.owners_by_key.each do |key, owners|
            if (loaded_owner = owners.find { |owner| loader.loaded?(owner) })
              already[key] = loader.target_for(loaded_owner)
            else
              keys << key
            end
          end
        end
        keys.subtract(already.keys)
        first = loaders.first
        loaded = if keys.empty?
          []
        else
          first.scope.where(first.association_key_name => keys).load { |record| loaders.each { |l| l.set_inverse(record) } }.to_a
        end
        raw = loaded + already.values.flatten
        loaders.each { |loader| loader.load_records(raw) }
      end
    end

    # Preloader::Association, for one planned association and its owners.
    class Loader
      attr_reader :node, :scope, :association_key_name, :query_key, :preloaded_records

      def initialize(node, owners, (scope, values))
        @node = node
        @reflection = node.reflection
        @klass = @reflection.klass
        @owners = owners.uniq(&:__id__)
        @scope = scope
        @association_key_name = @reflection.join_primary_key(@klass)
        @owner_key_name = @reflection.join_foreign_key
        @query_key = [@klass, @association_key_name, values]
        model = @owners.first.class
        @convert = @klass.type_for_attribute(@association_key_name).type != model.type_for_attribute(@owner_key_name).type
      end

      def owners_by_key
        @owners_by_key ||= @owners.each_with_object({}) do |owner, result|
          key = convert(owner._read_attribute(@owner_key_name))
          (result[key] ||= []) << owner if key
        end
      end

      def loaded?(owner)
        owner.association(@reflection.name).loaded?
      end

      def target_for(owner)
        Array.wrap(owner.association(@reflection.name).target)
      end

      def set_inverse(record)
        if (owners = owners_by_key[convert(record._read_attribute(@association_key_name))])
          owners.first.association(@reflection.name).set_inverse_instance(record)
        end
      end

      def load_records(raw_records)
        @records_by_owner = {}.compare_by_identity
        @preloaded_records = raw_records.select do |record|
          assigned = false
          owners_by_key[convert(record._read_attribute(@association_key_name))]&.each do |owner|
            entries = (@records_by_owner[owner] ||= [])
            if @reflection.collection? || entries.empty?
              entries << record
              assigned = true
            end
          end
          assigned
        end
      end

      def run
        @owners.each do |owner|
          next if loaded?(owner)

          association = owner.association(@reflection.name)
          records = @records_by_owner[owner] || []
          if @reflection.collection?
            association.target = records + association.target.reject(&:persisted?)
          else
            association.target = records.first
          end
        end
      end

      private

      def convert(key)
        @convert ? key.to_s : key
      end
    end
  end
end
